from collections import deque

def bfs(n, m, edges, s):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    distance = [-1] * (n + 1)
    distance[s] = 0
    q = deque([s])

    while q:
        current = q.popleft()
        for neighbor in adj[current]:
            if distance[neighbor] == -1:
                distance[neighbor] = distance[current] + 1
                q.append(neighbor)

    result = []
    for node in range(1, n + 1):
        if node == s:
            continue
        if distance[node] == -1:
            result.append(-1)
        else:
            result.append(distance[node] * 6)
    return result

